 function isCurrent(value){try{if(disposed||value.ticket!==serial||!gate.allowed()||!sameTarget(value.target,repository.captureTarget()))return false;const root=adapter.peekConfirmed(value.target);return equal(worldDynamicsOf(root),authority?.worldDynamics)&&equal(projectionTime(timeOf(root)),projectionTime(authority?.time))&&equal(source(value.target),value.reply)&&getContext().chat[value.reply.floor]?.mes===authority?.sourceText&&(value.mode==='regex'||getTheme()===value.theme);}catch{return false;}}
